effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
//////////////////////////
vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 TanRyu;
    TanRyu = acScreenNorm.st; 

    /////////////////////////

     int radius = int(RADIUSS);

	vec4 fragColor;

    	 vec2 src_size = vec2 (1.0 / iResolution.x, 1.0 / iResolution.y);
         vec2 uv = TanRyu;
         float n = float((radius + 1) * (radius + 1));
         int i; 
    	 int j;
         vec3 m0 = vec3(0.0); vec3 m1 = vec3(0.0); vec3 m2 = vec3(0.0); vec3 m3 = vec3(0.0);
         vec3 s0 = vec3(0.0); vec3 s1 = vec3(0.0); vec3 s2 = vec3(0.0); vec3 s3 = vec3(0.0);
         vec3 c;

         for (int j = -radius; j <= 0; ++j)  {
             for (int i = -radius; i <= 0; ++i)  {
                 c = texture2DCv(inputImg.texture, uv + vec2(i,j) * src_size).rgb;
                 m0 += c;
                 s0 += c * c;
             }
         }

         for (int j = -radius; j <= 0; ++j)  {
             for (int i = 0; i <= radius; ++i)  {
                 c = texture2DCv(inputImg.texture, uv + vec2(i,j) * src_size).rgb;
                 m1 += c;
                 s1 += c * c;
             }
         }

         for (int j = 0; j <= radius; ++j)  {
             for (int i = 0; i <= radius; ++i)  {
                 c = texture2DCv(inputImg.texture, uv + vec2(i,j) * src_size).rgb;
                 m2 += c;
                 s2 += c * c;
             }
         }

         for (int j = 0; j <= radius; ++j)  {
             for (int i = -radius; i <= 0; ++i)  {
                 c = texture2DCv(inputImg.texture, uv + vec2(i,j) * src_size).rgb;
                 m3 += c;
                 s3 += c * c;
             }
         }


         float min_sigma2 = 1e+2;
         m0 /= n;
         s0 = abs(s0 / n - m0 * m0);

         float sigma2 = s0.r + s0.g + s0.b;
         if (sigma2 < min_sigma2) {
             min_sigma2 = sigma2;
             fragColor = vec4(m0, 1.0);
         }

         m1 /= n;
         s1 = abs(s1 / n - m1 * m1);

         sigma2 = s1.r + s1.g + s1.b;
         if (sigma2 < min_sigma2) {
             min_sigma2 = sigma2;
             fragColor = vec4(m1, 1.0);
         }

         m2 /= n;
         s2 = abs(s2 / n - m2 * m2);

         sigma2 = s2.r + s2.g + s2.b;
         if (sigma2 < min_sigma2) {
             min_sigma2 = sigma2;
             fragColor = vec4(m2, 1.0);
         }

         m3 /= n;
         s3 = abs(s3 / n - m3 * m3);

         sigma2 = s3.r + s3.g + s3.b;
         if (sigma2 < min_sigma2) {
             min_sigma2 = sigma2;
             fragColor = vec4(m3, 1.0);
         }

	vec4 factor = mix(texColorX,fragColor,1.0);

	gl_FragColor = mix(texColor, factor, alpha) * texColor.a;
      }
    }
